import csv,collections,datetime
M='Belles_cookbook_store'
dists={10:collections.Counter(),'mar':collections.Counter(),'jan':collections.Counter()}
rows=collections.Counter(); amounts=collections.defaultdict(float); counts=collections.Counter(); fraudvals=collections.defaultdict(lambda: collections.Counter())
fraud_details=collections.defaultdict(lambda: {'n':0,'vol':0.0,'fees':collections.Counter()})
with open('inputs/payments.csv',newline='') as f:
 for r in csv.DictReader(f):
  if r['merchant']"'!=M: continue
  dt=datetime.date(2023,1,1)+datetime.timedelta(days=int(r['"'day_of_year'])-1)
  key=(r['card_scheme'],r['is_credit'],r['aci'],r['issuing_country']==r['acquirer_country'],r['issuing_country'],r['acquirer_country'],r['has_fraudulent_dispute'])
  if dt.day==10: dists[10][key]+=1
  if dt.month==3: dists['mar'][key]+=1
  if dt.month==1:
   dists['jan'][key]+=1
   if r['has_fraudulent_dispute']=='True':
    z=fraud_details[(r['card_scheme'],r['aci'])]; z['n']+=1;z['vol']+=float(r['eur_amount']);z['fees'][r['is_credit']]+=1
print('day10 total',sum(dists[10].values()),'distinct',len(dists[10]))
for k,n in sorted(dists[10].items()): print(n,k)
print('\\nMarch total',sum(dists['mar'].values()),'distinct',len(dists['mar']))
for k,n in sorted(dists['mar'].items()): print(n,k)
print('\\nJan total',sum(dists['jan'].values()),'distinct',len(dists['jan']))
for k,n in sorted(dists['jan'].items()): print(n,k)
print('\\nJan fraud by scheme/aci')
for k,z in sorted(fraud_details.items()): print(k,z)
